import{_ as o,o as r,c as t,a2 as s}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"27 - Service Layer","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/27-service-layer.md","filePath":"developers/design-documentation/27-service-layer.md"}'),i={name:"developers/design-documentation/27-service-layer.md"};function c(d,e,a,n,l,p){return r(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="_27-service-layer" tabindex="-1">27 - Service Layer <a class="header-anchor" href="#_27-service-layer" aria-label="Permalink to &quot;27 - Service Layer&quot;">​</a></h1><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><p>Services sit between Flask resources/blueprints and broker, database, sandbox, messaging, or calculation modules. A service should accept plain validated values, return plain result data plus status, and remain reusable outside a specific HTTP route where practical.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RESTX or blueprint</span></span>
<span class="line"><span>  -&gt; input/session validation</span></span>
<span class="line"><span>  -&gt; services/&lt;domain&gt;_service.py</span></span>
<span class="line"><span>     -&gt; auth/mode policy</span></span>
<span class="line"><span>     -&gt; broker module, sandbox manager, database, or pure calculation</span></span>
<span class="line"><span>  -&gt; HTTP response</span></span></code></pre></div><h2 id="service-families" tabindex="-1">Service Families <a class="header-anchor" href="#service-families" aria-label="Permalink to &quot;Service Families&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>Representative modules</th></tr></thead><tbody><tr><td>Order execution</td><td><code>place_order_service.py</code>, <code>place_smart_order_service.py</code>, <code>basket_order_service.py</code>, <code>split_order_service.py</code>, <code>place_options_order_service.py</code>, <code>options_multiorder_service.py</code></td></tr><tr><td>Order lifecycle</td><td><code>modify_order_service.py</code>, <code>cancel_order_service.py</code>, <code>cancel_all_order_service.py</code>, <code>close_position_service.py</code>, <code>orderstatus_service.py</code></td></tr><tr><td>Routing/approval</td><td><code>order_router_service.py</code>, <code>action_center_service.py</code>, <code>pending_order_execution_service.py</code></td></tr><tr><td>GTT</td><td><code>place_gtt_order_service.py</code>, <code>modify_gtt_order_service.py</code>, <code>cancel_gtt_order_service.py</code>, <code>gtt_orderbook_service.py</code></td></tr><tr><td>Account</td><td><code>funds_service.py</code>, <code>margin_service.py</code>, <code>orderbook_service.py</code>, <code>tradebook_service.py</code>, <code>positionbook_service.py</code>, <code>holdings_service.py</code>, <code>openposition_service.py</code></td></tr><tr><td>Market data</td><td><code>quotes_service.py</code>, <code>depth_service.py</code>, <code>history_service.py</code>, <code>instruments_service.py</code>, <code>intervals_service.py</code>, <code>search_service.py</code>, <code>symbol_service.py</code>, <code>expiry_service.py</code></td></tr><tr><td>Options analytics</td><td><code>option_chain_service.py</code>, <code>option_greeks_service.py</code>, <code>option_symbol_service.py</code>, <code>synthetic_future_service.py</code></td></tr><tr><td>Tools</td><td><code>gex_service.py</code>, <code>gamma_density_service.py</code>, <code>iv_chart_service.py</code>, <code>iv_smile_service.py</code>, <code>oi_tracker_service.py</code>, <code>oi_profile_service.py</code>, <code>vol_surface_service.py</code>, <code>straddle_chart_service.py</code>, <code>custom_straddle_service.py</code>, <code>arbitrage_service.py</code></td></tr><tr><td>Portfolio and analytics</td><td><code>portfolio_service.py</code>, <code>sip_service.py</code>, <code>strategy_pnl_service.py</code>, <code>indicator_service.py</code>, <code>chart_service.py</code></td></tr><tr><td>Automation</td><td><code>flow_executor_service.py</code>, <code>flow_scheduler_service.py</code>, <code>flow_price_monitor_service.py</code>, <code>flow_order_update_monitor_service.py</code>, <code>flow_workflow_validator.py</code>, <code>flow_tradeboard_client.py</code>, <code>historify_service.py</code>, <code>historify_scheduler_service.py</code></td></tr><tr><td>Messaging</td><td><code>telegram_alert_service.py</code>, <code>telegram_bot_service.py</code>, <code>whatsapp_alert_service.py</code>, <code>whatsapp_bot_service.py</code></td></tr><tr><td>Runtime</td><td><code>broker_keepalive_service.py</code>, <code>order_update_service.py</code>, <code>websocket_service.py</code>, <code>websocket_client.py</code>, <code>scalping_risk_monitor_service.py</code></td></tr></tbody></table><p>Use <code>rg --files services</code> for the exact inventory; this table describes ownership rather than freezing a file count.</p><h2 id="order-policy" tabindex="-1">Order Policy <a class="header-anchor" href="#order-policy" aria-label="Permalink to &quot;Order Policy&quot;">​</a></h2><p>Order services are responsible for:</p><ol><li>Verifying the API key and resolving the active broker/user context.</li><li>Respecting analyzer mode and routing supported requests to sandbox managers.</li><li>Respecting auto/semi-auto policy and Action Center eligibility.</li><li>Lazy-importing the correct broker module in live mode.</li><li>Returning normalized status and publishing one appropriate typed event.</li></ol><p>Batch services suppress per-child EventBus publication and emit one summary event. Basket execution sorts BUY before SELL and uses live concurrent batches of 10; split execution caps at 100 children and paces live calls from <code>ORDER_RATE_LIMIT</code>.</p><h2 id="market-and-options-policy" tabindex="-1">Market And Options Policy <a class="header-anchor" href="#market-and-options-policy" aria-label="Permalink to &quot;Market And Options Policy&quot;">​</a></h2><p>Market-data services normalize broker access without claiming every broker payload is identical. <code>history_service.py</code> owns <code>source=api</code> versus <code>source=db</code>. Option Greeks use Black-76 with automatic per-expiry synthetic forward resolution and spot fallback. Multi-Greeks batches option quotes and caps input at 50 symbols.</p><h2 id="long-lived-services" tabindex="-1">Long-Lived Services <a class="header-anchor" href="#long-lived-services" aria-label="Permalink to &quot;Long-Lived Services&quot;">​</a></h2><p>Long-lived services need explicit start/stop ownership and cannot retain request-scoped sessions, and they must release scoped sessions themselves through <code>utils/db_sessions.remove_all_scoped_sessions()</code> because no request teardown covers them. The scalping risk monitor is a singleton that owns an internal market-data client; <code>order_update_service.py</code> keeps one order-update adapter per broker session and republishes broker pushes as <code>order.update</code>; the WebSocket proxy has separate lifecycle integration; schedulers restore persisted jobs at startup.</p><h2 id="errors-and-logging" tabindex="-1">Errors And Logging <a class="header-anchor" href="#errors-and-logging" aria-label="Permalink to &quot;Errors And Logging&quot;">​</a></h2><ul><li>Validation errors belong at the resource/schema boundary when possible.</li><li>Services translate expected unsupported/missing-module states to stable status codes.</li><li>Do not include decrypted secrets or raw API keys in logs or returned error strings.</li><li>Subscriber failures must not change the order HTTP result; EventBus dispatch is asynchronous and isolated.</li></ul><h2 id="adding-a-service" tabindex="-1">Adding A Service <a class="header-anchor" href="#adding-a-service" aria-label="Permalink to &quot;Adding A Service&quot;">​</a></h2><ol><li>Confirm behavior is shared or complex enough to live outside the route.</li><li>Use the existing auth, result tuple, logging, and broker import patterns for the domain.</li><li>Keep Flask globals out of reusable logic unless the surrounding services already define that boundary.</li><li>Add mode and failure-path tests proportional to risk.</li><li>Update this family map only if ownership changes meaningfully.</li></ol>`,19)])])}const v=o(i,[["render",c]]);export{u as __pageData,v as default};
